// J-98: Share > Export > Markdown (Preview) writes the document's text as a
// Markdown file. The fixture is generated by
// src-tauri/tests/fixtures/make_table_report.py. The journey judges the file on
// disk: the words of the page are in it (at least 90 %, the same bar as the
// Office exports in J-70), the heading and the table's cells included, and the
// format is offered with its Preview label. The Rust half is
// src-tauri/tests/structured_export_files.rs.

import { readFileSync } from 'node:fs';
import { expect } from 'vitest';
import { journey } from './lib/journey';
import { exportAs, openExport, closeExportDialog } from './lib/export';
import { kept } from './lib/office';
import { allText } from './lib/pdfcheck';

journey('J-98', async (j) => {
  const doc = j.fixture('src-tauri/tests/fixtures/table_report.pdf', 'report.pdf');
  const source = allText(j.inspect(doc));
  await j.start({ open: doc });

  await j.step('the dialog offers Markdown and says it is a preview', async () => {
    const labels = await openExport(j, 'markdown');
    expect(labels.some((l) => /markdown/i.test(l) && /preview/i.test(l)), JSON.stringify(labels)).toBe(true);
    await closeExportDialog(j);
  });

  await j.step('export as Markdown; the file carries the page', async () => {
    const dest = j.file('report.md');
    await exportAs(j, 'markdown', dest);
    const md = readFileSync(dest, 'utf8');
    const share = kept(source, md);
    j.note(`markdown: ${Math.round(share * 100)} % of the words kept`);
    expect(share, `the Markdown kept ${Math.round(share * 100)} % of the words`).toBeGreaterThanOrEqual(0.9);
    for (const cell of ['Quarterly stock report', 'Widget', 'Gadget', 'Gizmo']) {
      expect(md, `the Markdown has ${cell}`).toContain(cell);
    }
  });
});
